local _, addon = ...
addon.localeData.frFR.texts = {
    FIREBALL = { name = "Boule de feu", ziel = { "Sentez la chaleur, %s !", "*lance Boule de feu sur %s.*", "%s, votre armure ne remplacera jamais une protection contre le feu." }, gruppe = { "Sentez la chaleur !", "*incante Boule de feu.*", "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "La flamme obéit à ma main, pas à mon humeur.", "*referme les doigts sur un noyau incandescent avant de le projeter.*" } },
    FROSTBOLT = { name = "Éclair de givre", ziel = { "Un salut glacé, %s !", "*lance Éclair de givre sur %s.*", "%s, chacun de vos pas sera désormais plus pénible." }, gruppe = { "Un salut glacé !", "*incante Éclair de givre.*", "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "L'hiver n'attend aucune invitation.", "*arrache un éclat de glace acéré à l'air humide.*" } },
    ARCANE_MISSILES = { name = "Projectiles des Arcanes", ziel = { "Les énergies arcaniques vous cherchent, %s !", "*lance Projectiles des Arcanes sur %s.*", "%s, cinq pensées pour une seule cible." }, gruppe = { "Les énergies arcaniques vous cherchent !", "*incante Projectiles des Arcanes.*", "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Les projectiles trouveront leur chemin à travers le chaos.", "*divise un fil de lumière violette en étincelles guidées.*" } },
    FIRE_BLAST = { name = "Trait de feu", ziel = { "Une étincelle suffit, %s !", "*lance Trait de feu sur %s.*", "%s, inutile de vous infliger un long discours." }, gruppe = { "Une étincelle suffit !", "*incante Trait de feu.*", "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Un instant suffit quand l'étincelle est bien placée.", "*claque des doigts et embrase l'air dans un bruit sec.*" } },
    PYROBLAST = { name = "Explosion pyrotechnique", ziel = { "Place au grand brasier, %s !", "*lance Explosion pyrotechnique sur %s.*", "%s, cet enchantement mérite qu'on garde ses distances." }, gruppe = { "Place au grand brasier !", "*incante Explosion pyrotechnique.*", "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Les grandes flammes exigent une main sûre.", "*trace un vaste cercle de feu et le condense en une sphère rugissante.*" } },
    FLAMESTRIKE = { name = "Choc de flammes", ziel = { "Le sol lui-même brûlera !", "*lance Choc de flammes sur %s.*", "%s, surveillez plutôt l'endroit où vous posez les pieds." }, gruppe = { "Le sol lui-même brûlera !", "*incante Choc de flammes.*", "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Le sol se souvient de chaque sceau mal placé.", "*dessine un motif ardent sous les pieds de ses adversaires.*" } },
    SCORCH = { name = "Brûlure", ziel = { "Un avant-goût du feu, %s.", "*lance Brûlure sur %s.*", "%s, petite leçon de chaleur appliquée." }, gruppe = { "Un avant-goût du feu.", "*incante Brûlure.*", "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Toute flamme n'a pas vocation à devenir un brasier.", "*passe deux doigts dans l'air et laisse une fine traînée de braises.*" } },
    BLIZZARD = { name = "Blizzard", ziel = { "L'hiver est sans pitié !", "*lance Blizzard sur %s.*", "%s, vous feriez mieux de trouver un abri chaud." }, gruppe = { "L'hiver est sans pitié !", "*incante Blizzard.*", "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "Quand le ciel se tait, la neige prend la parole.", "*lève les bras et invoque une bourrasque de neige et de glace tranchante.*" } },
    FROST_NOVA = { name = "Nova de givre", ziel = { "Pas un pas de plus, %s !", "*lance Nova de givre sur %s.*", "%s, votre élan s'arrête ici." }, gruppe = { "Pas un pas de plus !", "*incante Nova de givre.*", "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "Le froid trace une frontière impossible à ignorer.", "*abaisse la paume vers le sol et répand le givre tout autour.*" } },
    CONE_OF_COLD = { name = "Cône de froid", ziel = { "Un souffle du nord !", "*lance Cône de froid sur %s.*", "%s, l'air de l'hiver vient à votre rencontre." }, gruppe = { "Un souffle du nord !", "*incante Cône de froid.*", "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "Un souffle suffit à rendre les environs bien peu accueillants.", "*écarte les doigts et projette devant soi une vague d'air glacial.*" } },
    ICE_BARRIER = { name = "Barrière de glace", ziel = {  }, gruppe = { "Le froid est mon bouclier.", "*incante Barrière de glace.*", "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Mon bouclier est tissé de patience et de givre.", "*superpose de fins cristaux de glace autour de son corps.*" } },
    ICE_BLOCK = { name = "Bloc de glace", ziel = {  }, gruppe = { "Je suis momentanément indisponible.", "*incante Bloc de glace.*", "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Certaines attaques ne méritent aucune réplique, seulement une pause.", "*ferme les yeux tandis qu'une gangue de glace translucide se forme.*" } },
    ARCANE_EXPLOSION = { name = "Explosion des Arcanes", ziel = { "Reculez, la magie s'agite !", "*lance Explosion des Arcanes sur %s.*", "%s, quittez mon cercle d'incantation." }, gruppe = { "Reculez, la magie s'agite !", "*incante Explosion des Arcanes.*", "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "La distance est parfois la plus sage des disciplines arcaniques.", "*écarte brusquement les bras et libère un anneau d'énergie violette.*" } },
    COUNTERSPELL = { name = "Contresort", ziel = { "Votre incantation s'arrête ici, %s !", "*lance Contresort sur %s.*", "%s, vos syllabes sont mal placées." }, gruppe = { "Votre incantation s'arrête ici !", "*incante Contresort.*", "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Il suffit de dérober une syllabe pour briser un sort.", "*coupe net une incantation ennemie d'un geste de deux doigts.*" } },
    POLYMORPH = { name = "Métamorphose", ziel = { "Un peu de laine vous va bien, %s.", "*lance Métamorphose sur %s.*", "%s, vous me sembliez bien plus grand il y a un instant." }, gruppe = { "Un peu de laine vous va bien.", "*incante Métamorphose.*", "Un peu de laine vous irait bien.", "*esquisse la silhouette d'un mouton.*", "Un peu d'humilité, quatre sabots et beaucoup de laine.", "*dessine un mouton de lumière dont la silhouette enveloppe la cible.*" } },
    BLINK = { name = "Transfert", ziel = {  }, gruppe = { "Un instant, je serai ailleurs.", "*incante Transfert.*", "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "Le chemin le plus court n'est pas toujours celui qu'on voit.", "*disparaît dans une mince fente de lumière bleue et réapparaît un battement de cœur plus tard.*" } },
    SLOW_FALL = { name = "Chute lente", ziel = { "La gravité attendra aujourd'hui.", "*lance Chute lente sur %s.*" }, gruppe = { "La gravité attendra aujourd'hui.", "*incante Chute lente.*", "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "La gravité fera une exception aujourd'hui.", "*dessine un arc léger comme une plume sous ses bottes.*" } },
    EVOCATION = { name = "Évocation", ziel = {  }, gruppe = { "Un instant pour rassembler mes pensées et mon mana.", "*incante Évocation.*", "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Même les grands arts ont parfois besoin de reprendre leur souffle.", "*ramène lentement des étincelles de mana vers ses paumes.*" } },
    ARCANE_INTELLECT = { name = "Intelligence des Arcanes", ziel = { "Un esprit vif est votre meilleure arme, %s.", "*lance Intelligence des Arcanes sur %s.*", "%s, que votre esprit soit plus aiguisé que votre lame." }, gruppe = { "Un esprit vif est votre meilleure arme.", "*incante Intelligence des Arcanes.*", "Un esprit vif est un beau cadeau.", "*transmet un glyphe lumineux.*", "Un esprit alerte est le plus fiable des talismans.", "*pose un petit glyphe lumineux contre sa tempe.*" } },
    ARCANE_BRILLIANCE = { name = "Illumination des Arcanes", ziel = { "Que nos esprits brillent davantage !", "*lance Illumination des Arcanes sur %s.*", "%s, le savoir gagne à être partagé." }, gruppe = { "Que nos esprits brillent davantage !", "*incante Illumination des Arcanes.*", "Un esprit vif est un beau cadeau.", "*transmet un glyphe lumineux.*", "Les meilleurs compagnons sont ceux qui réfléchissent ensemble.", "*déploie un réseau de runes lumineuses sur ses alliés.*" } },
    MANA_SHIELD = { name = "Bouclier de mana", ziel = {  }, gruppe = { "Le mana me protège, la pensée devient acier.", "*incante Bouclier de mana.*", "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Mes pensées sont plus difficiles à percer que ma robe.", "*enroule des fils de mana autour de ses épaules.*" } },
    CONJURE_FOOD = { name = "Invocation de nourriture", ziel = {  }, gruppe = { "Un peu de magie contre la faim.", "*incante Invocation de nourriture.*", "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "La bonne magie sait aussi apaiser la faim.", "*ouvre les mains et fait apparaître une collation encore parfumée.*" } },
    CONJURE_WATER = { name = "Invocation d'eau", ziel = {  }, gruppe = { "De l'eau fraîche, née de la magie.", "*incante Invocation d'eau.*", "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Buvez. L'étude des arcanes donne soif.", "*attrape une goutte de lumière et la transforme en eau limpide.*" } },
    CREATE_MANA_GEM = { name = "Invocation d'une gemme de mana", ziel = {  }, gruppe = { "Une petite réserve pour les urgences.", "*incante Invocation d'une gemme de mana.*", "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Une petite réserve pour un gros problème.", "*condense du mana vacillant en une gemme froide et lumineuse.*" } },
    PORTAL = { name = "Portail", ziel = {  }, gruppe = { "Attention à vos membres en traversant.", "*incante Portail.*", "Gardez vos membres à l'intérieur du portail.", "*vérifie deux fois les coordonnées.*", "Quiconque franchit ce seuil doit se fier au cercle de destination.", "*ouvre avec précaution un pli circulaire dans le tissu de l'espace.*" } },
    TELEPORT = { name = "Téléportation", ziel = {  }, gruppe = { "Je prends un raccourci à travers l'espace.", "*incante Téléportation.*", "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "Un pas, une erreur de coordonnées, mille lieues d'écart.", "*trace la rune de destination et se dissout dans un tourbillon de lumière.*" } },
    REMOVE_LESSER_CURSE = { name = "Délivrance de la malédiction mineure", ziel = { "Cette malédiction n'a pas sa place ici, %s.", "*lance Délivrance de la malédiction mineure sur %s.*", "%s, cette malédiction s'est assez longtemps accrochée à vous." }, gruppe = { "Cette malédiction n'a pas sa place ici.", "*incante Délivrance de la malédiction mineure.*", "Il existe une formule pour presque tout.", "*ouvre un grimoire à la bonne page.*", "Aucun enchantement ne résiste à qui sait en défaire les nœuds.", "*détache une ombre d'une épaule à l'aide d'une rune lumineuse.*" } },
    DETECT_MAGIC = { name = "Détection de la magie", ziel = { "Voyons quels secrets vous portez, %s.", "*lance Détection de la magie sur %s.*", "%s, votre aura en dit plus long que vos paroles." }, gruppe = { "Voyons quels secrets vous portez.", "*incante Détection de la magie.*", "Il existe une formule pour presque tout.", "*ouvre un grimoire à la bonne page.*", "Les courants cachés laissent toujours une trace.", "*tend un sceau scintillant vers la lumière et observe sa réaction.*" } },
    DAMPEN_MAGIC = { name = "Atténuation de la magie", ziel = { "%s, un peu moins de vacarme magique vous fera du bien.", "Toute puissance n'a pas besoin de parler à pleine voix.", "*dépose un voile argenté sur les courants de mana palpitants.*" }, gruppe = { "Un esprit vif est un beau cadeau.", "*transmet un glyphe lumineux.*", "Toute puissance n'a pas besoin de parler à pleine voix.", "*dépose un voile argenté sur les courants de mana palpitants.*" } },
    AMPLIFY_MAGIC = { name = "Amplification de la magie", ziel = { "%s, j'ouvre vos sens à des courants plus puissants.", "Un surcroît de pouvoir n'est un cadeau que si on sait le guider.", "*élargit d'un geste mesuré le cercle lumineux autour d'un allié.*" }, gruppe = { "Un esprit vif est un beau cadeau.", "*transmet un glyphe lumineux.*", "Un surcroît de pouvoir n'est un cadeau que si on sait le guider.", "*élargit d'un geste mesuré le cercle lumineux autour d'un allié.*" } },
    FROST_ARMOR = { name = "Armure de givre", ziel = {  }, gruppe = { "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Une tête froide mérite une armure à sa mesure.", "*dessine un liseré de givre scintillant autour de ses épaules et de ses bras.*" } },
    ICE_ARMOR = { name = "Armure de glace", ziel = {  }, gruppe = { "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Quiconque me touchera devra d'abord saluer l'hiver.", "*fait croître des écailles de glace dure sur sa robe.*" } },
    MAGE_ARMOR = { name = "Armure du mage", ziel = {  }, gruppe = { "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "La discipline des arcanes commence juste sous ma robe.", "*fait scintiller une couche presque invisible de glyphes protecteurs.*" } },
    FIRE_WARD = { name = "Gardien de feu", ziel = {  }, gruppe = { "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "Le feu reconnaît le feu, mais toute flamme ne peut franchir ce seuil.", "*referme un anneau d'or incandescent en sceau protecteur.*" } },
    FROST_WARD = { name = "Gardien de givre", ziel = {  }, gruppe = { "La prudence est un art, pas une faiblesse.", "*trace un cercle protecteur scintillant.*", "L'hiver frappe. Ma réponse est déjà prête.", "*dresse un cercle de cristal transparent contre l'air glacé.*" } },
    ARCANE_BLAST = { name = "Déflagration des arcanes", ziel = { "%s, vous ne pourrez pas discuter avec cette énergie.", "La puissance brute n'a nul besoin de flammes pour laisser sa marque.", "*projette une onde dense de lumière violette.*" }, gruppe = { "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "La puissance brute n'a nul besoin de flammes pour laisser sa marque.", "*projette une onde dense de lumière violette.*" } },
    ARCANE_WRATH = { name = "Courroux des arcanes", ziel = { "%s, ma patience était votre dernière protection.", "Les arcanes répondent à la sottise avec vigueur.", "*tord deux sceaux flottants jusqu'à faire jaillir une décharge lumineuse.*" }, gruppe = { "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Les arcanes répondent à la sottise avec vigueur.", "*tord deux sceaux flottants jusqu'à faire jaillir une décharge lumineuse.*" } },
    ARCANE_POWER = { name = "Pouvoir des arcanes", ziel = {  }, gruppe = { "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Il est temps pour la théorie de prouver sa véritable valeur.", "*ouvre les mains tandis que des cercles runiques accélèrent leur rotation.*" } },
    PRESENCE_OF_MIND = { name = "Présence spirituelle", ziel = {  }, gruppe = { "L'équation est élégante. Les conséquences, moins.", "*aligne des glyphes violets.*", "Certaines pensées vont plus vite que la parole.", "*s'immobilise un instant comme si tous les chemins devenaient visibles à la fois.*" } },
    BLAST_WAVE = { name = "Vague explosive", ziel = { "%s, vous êtes trop près de mon centre.", "Quand l'air riposte, mieux vaut prendre ses distances.", "*frappe dans ses mains et libère une onde de choc brûlante.*" }, gruppe = { "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Quand l'air riposte, mieux vaut prendre ses distances.", "*frappe dans ses mains et libère une onde de choc brûlante.*" } },
    COMBUSTION = { name = "Combustion", ziel = {  }, gruppe = { "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Aujourd'hui, chaque braise donnera sa dernière étincelle.", "*attire la chaleur alentour dans une flamme unique et vacillante.*" } },
    FROSTFIRE_BOLT = { name = "Éclair de givrefeu", ziel = { "%s, choisissez vite entre le givre et les flammes.", "Une contradiction ? Seulement pour un mauvais mage.", "*entrelace des éclats de glace bleus et des filaments de feu rouges en un projectile.*" }, gruppe = { "Il existe une formule pour presque tout.", "*ouvre un grimoire à la bonne page.*", "Une contradiction ? Seulement pour un mauvais mage.", "*entrelace des éclats de glace bleus et des filaments de feu rouges en un projectile.*" } },
    FELFIRE = { name = "Gangrefeu", ziel = { "%s, même cette flamme étrangère obéit à un sceau bien tracé.", "Le feu vert exige davantage de prudence, pas moins de réflexion.", "*enferme une flamme verte instable dans un étroit anneau runique.*" }, gruppe = { "Le feu est un négociateur sincère.", "*fait danser des étincelles ambrées.*", "Le feu vert exige davantage de prudence, pas moins de réflexion.", "*enferme une flamme verte instable dans un étroit anneau runique.*" } },
    ICE_LANCE = { name = "Lance de glace", ziel = { "%s, un seul éclat suffira pour toute réponse.", "La glace n'a pas besoin d'être grande pour être tranchante.", "*condense du givre scintillant en une lance aussi fine qu'une aiguille.*" }, gruppe = { "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "La glace n'a pas besoin d'être grande pour être tranchante.", "*condense du givre scintillant en une lance aussi fine qu'une aiguille.*" } },
    FROST_BLAST = { name = "Explosion de givre", ziel = { "%s, cet hiver arrive sans avertissement.", "Le froid en un seul battement de cœur implacable.", "*déchaîne une violente rafale de givre depuis son poing ouvert.*" }, gruppe = { "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "Le froid en un seul battement de cœur implacable.", "*déchaîne une violente rafale de givre depuis son poing ouvert.*" } },
    COLD_SNAP = { name = "Morsure du froid", ziel = {  }, gruppe = { "Même l'air retient son souffle.", "*dessine un cercle de cristaux de glace.*", "Le temps n'est qu'une variable de plus dans l'art du givre.", "*brise un flocon suspendu et réorganise les glyphes de givre.*" } },
    CONJURE_MANA_AGATE = { name = "Invocation d'agate de mana", ziel = {  }, gruppe = { "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Une agate assez petite pour la poche et assez puissante pour sauver la mise.", "*verse un mince flot de mana dans une agate en formation.*" } },
    CONJURE_MANA_JADE = { name = "Invocation de jade de mana", ziel = {  }, gruppe = { "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Le jade conserve la magie presque aussi patiemment qu'un érudit.", "*dépose une lumière verte dans une gemme de mana parfaitement polie.*" } },
    CONJURE_MANA_CITRINE = { name = "Invocation de citrine de mana", ziel = {  }, gruppe = { "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Une touche de soleil doré pour les heures de fatigue.", "*façonne une citrine lumineuse à partir d'étincelles dorées.*" } },
    CONJURE_MANA_RUBY = { name = "Invocation de rubis de mana", ziel = {  }, gruppe = { "Un bon repas relève aussi de la haute magie.", "*secoue des étincelles de sa manche.*", "Ce rubis a vu passer plus de mana que certains bibliothécaires.", "*enferme des courants de mana cramoisis dans un rubis étincelant.*" } },
    POLYMORPH_COW = { name = "Métamorphose : vache", ziel = { "%s, j'espère que les cloches de vache ne vous dérangent pas.", "Aujourd'hui, quatre pattes et beaucoup d'herbe.", "*dessine la silhouette d'une vache avec des runes doucement lumineuses.*" }, gruppe = { "Un peu de laine vous irait bien.", "*esquisse la silhouette d'un mouton.*", "Aujourd'hui, quatre pattes et beaucoup d'herbe.", "*dessine la silhouette d'une vache avec des runes doucement lumineuses.*" } },
    COMPREHEND_SCROLL = { name = "Compréhension du parchemin", ziel = {  }, gruppe = { "Il existe une formule pour presque tout.", "*ouvre un grimoire à la bonne page.*", "Certains parchemins ne livrent leur sens qu'aux regards patients.", "*lève un parchemin vers la lumière et dénoue ses symboles scellés.*" } },
    STUDY = { name = "Étude", ziel = {  }, gruppe = { "Il existe une formule pour presque tout.", "*ouvre un grimoire à la bonne page.*", "Qui lance des sorts sans jamais lire reste un apprenti.", "*lisse une annotation dans la marge d'un vieux grimoire.*" } },
    TELEPORT_STORMWIND = { name = "Téléportation : STORMWIND", ziel = {  }, gruppe = { "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "Hurlevent n'est qu'à une rune bien tracée.", "*replie l'image des tours blanches en un point de lumière tournoyant.*" } },
    PORTAL_STORMWIND = { name = "Portail : STORMWIND", ziel = {  }, gruppe = { "Gardez vos membres à l'intérieur du portail.", "*vérifie deux fois les coordonnées.*", "Un passage vers les portes de Hurlevent. Chacun son tour, je vous prie.", "*ouvre un portail bleu encadré par les remparts de la cité.*" } },
    TELEPORT_IRONFORGE = { name = "Téléportation : IRONFORGE", ziel = {  }, gruppe = { "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "Forgefer attend, entre le son des enclumes et la pierre chaude.", "*condense les contours d'une porte de montagne en rune de destination.*" } },
    PORTAL_IRONFORGE = { name = "Portail : IRONFORGE", ziel = {  }, gruppe = { "Gardez vos membres à l'intérieur du portail.", "*vérifie deux fois les coordonnées.*", "Si vous sentez la fumée des forges, Forgefer n'est plus loin.", "*ouvre un passage où scintillent un instant des étincelles de forge.*" } },
    TELEPORT_DARNASSUS = { name = "Téléportation : DARNASSUS", ziel = {  }, gruppe = { "Le plus court chemin traverse parfois l'espace.", "*plie une carte en une étincelle.*", "Darnassus appelle, avec ses jardins paisibles et ses branches anciennes.", "*tisse une lueur argentée de feuilles dans le cercle de destination.*" } },
